const listDeviations = `-- name: ListDeviations :many
SELECT d.id, d.number, d.title, d.description, d.order_id, d.work_order_id, d.check_result_id, d.lot_id, d.lot_number, d.variant_id, d.disposition, d.status, d.quarantine, d.holds_released, d.opened_by_user_id, d.opened_by_display, d.opened_at, d.closed_by_user_id, d.closed_by_display, d.closed_at, d.closing_note, d.revision, d.station_id
FROM manufacturing.deviations d
LEFT JOIN manufacturing.orders o ON o.id = d.order_id
WHERE ($1::text IS NULL OR d.status = $1)
  AND ($2::bigint IS NULL OR d.order_id = $2)
  AND ($3::int IS NULL OR COALESCE(d.variant_id, o.variant_id) = $3)
  AND ($4::bigint IS NULL OR d.lot_id = $4
       OR EXISTS (SELECT 1 FROM manufacturing.deviation_lots l WHERE l.deviation_id = d.id AND l.lot_id = $4))
  AND ($5::timestamptz IS NULL OR d.opened_at >= $5)
  AND ($6::timestamptz IS NULL OR d.opened_at < $6)
ORDER BY d.opened_at DESC, d.id DESC
LIMIT $8 OFFSET $7
`

type ListDeviationsParams struct {
	Status     *string
	OrderID    *int64
	VariantID  *int32
	LotID      *int64
	FromAt     *time.Time
	ToAt       *time.Time
	PageOffset int32
	PageLimit  int32
}

type ListDeviationsRow struct {
	ManufacturingDeviation ManufacturingDeviation
}

// ListDeviations is a page of deviations by the filters, newest first.
func (q *Queries) ListDeviations(ctx context.Context, arg ListDeviationsParams) ([]ListDeviationsRow, error) {
	rows, err := q.db.Query(ctx, listDeviations,
		arg.Status,
		arg.OrderID,
		arg.VariantID,
		arg.LotID,
		arg.FromAt,
		arg.ToAt,
		arg.PageOffset,
		arg.PageLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListDeviationsRow
	for rows.Next() {
		var i ListDeviationsRow
		if err := rows.Scan(
			&i.ManufacturingDeviation.ID,
			&i.ManufacturingDeviation.Number,
			&i.ManufacturingDeviation.Title,
			&i.ManufacturingDeviation.Description,
			&i.ManufacturingDeviation.OrderID,
			&i.ManufacturingDeviation.WorkOrderID,
			&i.ManufacturingDeviation.CheckResultID,
			&i.ManufacturingDeviation.LotID,
			&i.ManufacturingDeviation.LotNumber,
			&i.ManufacturingDeviation.VariantID,
			&i.ManufacturingDeviation.Disposition,
			&i.ManufacturingDeviation.Status,
			&i.ManufacturingDeviation.Quarantine,
			&i.ManufacturingDeviation.HoldsReleased,
			&i.ManufacturingDeviation.OpenedByUserID,
			&i.ManufacturingDeviation.OpenedByDisplay,
			&i.ManufacturingDeviation.OpenedAt,
			&i.ManufacturingDeviation.ClosedByUserID,
			&i.ManufacturingDeviation.ClosedByDisplay,
			&i.ManufacturingDeviation.ClosedAt,
			&i.ManufacturingDeviation.ClosingNote,
			&i.ManufacturingDeviation.Revision,
			&i.ManufacturingDeviation.StationID,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

